const test   = require('node:test');
const assert = require('node:assert');
const { makeSandbox } = require('./helpers');

// ─── Fixture ──────────────────────────────────────────────────────────────────

// Fake IDs: the bot, an answer channel (also #general), a non-answer channel, and the staff role.
const BOT = 'bot1', ANSWER_CH = 'general', OTHER_CH = 'other', STAFF_ROLE = 'staffRole';

// Builds the handler in a sandbox; `intent` decides what the fake classifier returns, and `tweets`
// (status ID → tweet, or null for "can't be read") stands in for FxTwitter.
function setup({ intent = 'help-seeking', scamBlocker = true, tweets = {} } = {}) {
    const box = makeSandbox(['src/commands.js', 'src/toggles.js', 'src/state.js', 'src/utils.js', 'src/tweet-check.js'], {
        'data/toggles.json': JSON.stringify({ discord: true, telegram: true, 'scam-blocker': scamBlocker }),
    });
    const state = require(box.path('src/state.js'));
    const utils = require(box.path('src/utils.js'));
    const { registerMessageHandler } = require(box.path('src/commands.js'));
    const seen = { answered: [], learned: [], infractions: 0, deleted: 0, records: [], forwarded: [] };
    const handlers = {};
    const client = { on: (ev, fn) => { (handlers[ev] ??= []).push(fn); }, user: { id: BOT }, channels: { cache: new Map(), fetch: async (id) => (id === '1502041137119105054' ? { send: async (m) => seen.forwarded.push(m) } : null) } };
    registerMessageHandler(client, state, {
        BOT_ANSWER_CHANNEL_IDS: [ANSWER_CH], STAFF_ROLE_IDS: [STAFF_ROLE], GENERAL_CHANNEL_ID: ANSWER_CH, SUPPORT_CHANNEL_ID: 'support',
        SUPPORT_TICKET_CATEGORY_IDS: new Set(['ticketCat']), COLLAB_CATEGORY_IDS: new Set(),
    }, {
        claude: { answerQuestion: async (a) => seen.answered.push(a.question), identifyRelevantSources: () => [] },
        intent: {
            classifyMessageIntent: async () => intent, logMessageIntent: () => {}, logIntentClassification: () => {},
            RESPOND_INTENTS: new Set(['help-seeking', 'troubleshooting', 'onboarding', 'factual-question']),
            logToTicketFile: () => {}, logToCollabFile: () => {},
            hasSoftScamSignal: (t) => /\b(inbox|dm)\b/i.test(t),
        },
        kbSync: {},
        utils: { ...utils, saveQAPair: (ch, q, a) => seen.learned.push({ q, a }), appendToMonthlyWeeklyFile: () => {} },
        buildIndex: async () => {}, searchKB: async () => ({ context: '', sources: [] }), htmlToMarkdown: async () => '',
        EmbedBuilder: class {},
        scamTracker: {
            recordInfraction: (id, rec) => { seen.records.push(rec); return ++seen.infractions; },
            updateInfractionActions: () => {},
            updateInfractionEvidence: (id, n, patch) => Object.assign(seen.records[n - 1].evidence, patch),
            getAllRecords: () => ({}),
        },
        tweetChecker: require(box.path('src/tweet-check.js')).createTweetChecker({
            fetchTweet: async (id) => (tweets[id] ?? { error: 'NOT_FOUND' }),
        }),
    });
    // Clears pending auto-answer timers (or the test process would wait for them) and deletes the sandbox.
    const done = () => { for (const [, v] of state.pendingQuestions) clearTimeout(v.timer); box.cleanup(); };
    return {
        handler: (m) => Promise.all(handlers.messageCreate.map(f => f(m))),
        deleted: (m) => Promise.all(handlers.messageDelete.map(f => f(m))),
        state, seen, done,
    };
}

// A fake Discord message. `replyTo` is { id, authorId, ping }; `staff` gives the sender the staff role.
function msg(channelId, content, { replyTo = null, staff = false, mentionBot = false, id = `m${Math.random()}` } = {}) {
    const ref = replyTo && { id: replyTo.id, author: { id: replyTo.authorId, bot: replyTo.authorId === BOT }, content: 'earlier answer', reference: null };
    const roles = new Map(staff ? [[STAFF_ROLE, {}]] : []);
    return {
        id, content: mentionBot ? `<@${BOT}> ${content}` : content, channelId,
        guild: { members: { fetch: async () => null } },
        author: { id: staff ? 'staff1' : 'user1', bot: false, username: 'u', tag: 'u#1' },
        member: { roles: { cache: roles }, displayName: 'u', timeout: async () => {} },
        mentions: { users: new Map(mentionBot ? [[BOT, {}]] : []), repliedUser: replyTo?.ping ? { id: replyTo.authorId } : null },
        reference: replyTo ? { messageId: replyTo.id } : null, attachments: new Map(),
        channel: { parentId: null, name: channelId, messages: { cache: new Map(), fetch: async () => ref } },
        reply: async () => ({ id: 'r1' }), delete: async function () { this.deleted = true; },
    };
}

// ─── Channel gate ─────────────────────────────────────────────────────────────

test('channel gate: replies to the bot work in any channel; unprompted answers only in answer channels', async () => {
    const t = setup();
    try {
        await t.handler(msg(OTHER_CH, 'how do I stake river'));
        assert.strictEqual(t.seen.answered.length, 0, 'plain message outside answer channels is ignored');
        await t.handler(msg(OTHER_CH, 'and what about unlocks', { replyTo: { id: 'b1', authorId: BOT, ping: true } }));
        assert.strictEqual(t.seen.answered.length, 1, 'reply to the bot (pinged) is answered');
        await t.handler(msg(OTHER_CH, 'and what about unlocks', { replyTo: { id: 'b2', authorId: BOT, ping: false } }));
        assert.strictEqual(t.seen.answered.length, 2, 'reply to the bot (no ping) is answered');
        await t.handler(msg(OTHER_CH, 'how do I stake river', { replyTo: { id: 'p1', authorId: 'someone', ping: true } }));
        assert.strictEqual(t.seen.answered.length, 2, 'reply to a person outside answer channels is ignored');
        await t.handler(msg(OTHER_CH, 'thanks', { replyTo: { id: 'b3', authorId: BOT, ping: true } }));
        assert.strictEqual(t.state.pendingQuestions.size, 0, 'one-word reply outside answer channels is not queued');
        await t.handler(msg(ANSWER_CH, 'how do I stake river'));
        assert.strictEqual(t.state.pendingQuestions.size, 1, 'question in an answer channel is queued for auto-answer');
    } finally { t.done(); }
});

test('a question deleted while waiting for its auto-answer is dropped', async () => {
    const t = setup();
    try {
        await t.handler(msg(ANSWER_CH, 'how do I stake river', { id: 'ask1' }));
        assert.strictEqual(t.state.pendingQuestions.size, 1);
        t.deleted({ id: 'ask1' });
        assert.strictEqual(t.state.pendingQuestions.size, 0, 'pending answer cancelled');
        assert.strictEqual(t.state.pendingMsgIndex.size, 0);
    } finally { t.done(); }
});

// ─── Scam blocker ─────────────────────────────────────────────────────────────

test('scam blocker never acts on staff, but does act on non-staff', async () => {
    const t = setup({ intent: 'scam-content' });
    try {
        const staffMsg = msg(OTHER_CH, 'is t.me/someone legit?', { staff: true, mentionBot: true });
        await t.handler(staffMsg);
        assert.strictEqual(staffMsg.deleted, undefined, 'staff message not deleted');
        assert.strictEqual(t.seen.infractions, 0, 'no infraction recorded for staff');
        const userMsg = msg(OTHER_CH, 'dm me for help', { mentionBot: true });
        await t.handler(userMsg);
        assert.strictEqual(userMsg.deleted, true, 'non-staff scam message deleted');
        assert.strictEqual(t.seen.infractions, 1, 'infraction recorded for non-staff');
    } finally { t.done(); }
});

test('scam blocker keeps evidence: the replied-to message, attachments and link previews', async () => {
    const t = setup({ intent: 'scam-content' });
    try {
        const m = msg(ANSWER_CH, 'check dm', { replyTo: { id: 'q1', authorId: 'victim', ping: true } });
        m.attachments = new Map([['a1', { name: 'shot.png', contentType: 'image/png' }]]);
        m.embeds = [{ url: 'https://x.com/a/status/1', author: { name: 'Support Desk' }, description: 'Create a ticket https://discord.gg/x' }];
        await t.handler(m);
        await new Promise(r => setImmediate(r));   // the replied-to message is fetched in the background
        assert.strictEqual(t.seen.forwarded.length, 2, 'the Discord invite in the link preview is reported as an AutoMod miss');
        assert.match(t.seen.forwarded[0].content, /discord\.gg\/x/);
        assert.strictEqual(t.seen.forwarded[1].content, 'check dm', 'followed by the original message, exactly as written');
        assert.deepStrictEqual(t.seen.forwarded[0].allowedMentions, { parse: [] }, 'nobody is pinged');
        const ev = t.seen.records[0].evidence;
        assert.deepStrictEqual(ev.attachments, [{ name: 'shot.png', type: 'image/png' }]);
        assert.strictEqual(ev.previews[0].author, 'Support Desk');
        assert.match(ev.previews[0].text, /discord\.gg/);
        assert.strictEqual(ev.repliedToId, 'q1');
        assert.strictEqual(ev.repliedTo.authorId, 'victim', 'who the scammer was targeting');
    } finally { t.done(); }
});

test('linked tweets: a fake help desk is blocked at once, an ordinary tweet is spared, an unreadable one is deleted unpunished', async () => {
    const t = setup({
        intent: 'scam-content',   // the classifier calls every bare link scam — the tweet check must overrule it
        tweets: {
            '111': { name: 'CREATE A TICKET', handle: 'createticket_x', text: 'Create a ticket 👉 https://discord.gg/abc', followers: 3 },
            '222': { name: 'NHK', handle: 'langtusg0308', text: 'Shit project !', hasMedia: true, followers: 9352 },
        },
    });
    try {
        const desk = msg(ANSWER_CH, 'https://x.com/createticket_x/status/111');
        await t.handler(desk);
        assert.strictEqual(desk.deleted, true, 'fake help-desk tweet: deleted');
        assert.match(t.seen.records[0].reason, /^scam-tweet: fake help-desk tweet/);
        assert.strictEqual(t.seen.records[0].evidence.tweets[0].text, 'Create a ticket 👉 https://discord.gg/abc');
        assert.strictEqual(t.seen.forwarded.length, 2, 'reposted to #ai: a header, then the message itself');
        assert.match(t.seen.forwarded[0].content, /invite is inside the linked tweet/);
        assert.strictEqual(t.seen.forwarded[1].content, 'https://x.com/createticket_x/status/111', 'the original message, exactly as written');

        const genuine = msg(ANSWER_CH, 'https://x.com/langtusg0308/status/222');
        await t.handler(genuine);
        assert.strictEqual(genuine.deleted, undefined, 'ordinary tweet: left alone');
        assert.strictEqual(t.seen.infractions, 1, 'and no offence recorded');

        // Unreadable tweets (removed by X, or FxTwitter down):
        const plain = msg(ANSWER_CH, 'https://x.com/i/status/333');
        await t.handler(plain);
        assert.strictEqual(plain.deleted, undefined, 'no second sign: left up');
        assert.match(t.seen.forwarded[2].content, /no other scam sign — left up, please review/, 'and forwarded to #ai');
        assert.strictEqual(t.seen.forwarded[3].content, 'https://x.com/i/status/333', 'followed by the message exactly as written');

        const deskLink = msg(ANSWER_CH, 'https://x.com/supportdesk578/status/555');
        await t.handler(deskLink);
        assert.strictEqual(deskLink.deleted, true, 'the link names a fake help desk: deleted');
        assert.strictEqual(t.seen.infractions, 2, 'and treated as scam: offence recorded (so timeout)');
        assert.match(t.seen.records[1].reason, /linked tweet unreadable, link names @supportdesk578/);
        assert.strictEqual(t.seen.forwarded.length, 4, 'scam log only — not to #ai');
    } finally { t.done(); }
});

test('DM request left up in a conversation: the helper is flagged only if they later delete their messages', async () => {
    const t = setup({ intent: 'community-help' });   // classifier: help offered within a conversation, not scam
    try {
        const offer = msg(ANSWER_CH, 'I know the fix, I can explain it in your inbox, check inbox', { id: 'offer1', replyTo: { id: 'ask1', authorId: 'seeker' } });
        offer.guild.members.fetch = async () => offer.member;
        await t.handler(offer);
        assert.strictEqual(offer.deleted, undefined, 'the DM request stays up');
        assert.strictEqual(t.seen.infractions, 0, 'and is not punished');

        await t.deleted({ id: 'unrelated' });
        assert.strictEqual(t.seen.infractions, 0, 'deleting some other message changes nothing');

        await t.deleted({ id: 'offer1' });
        assert.strictEqual(t.seen.infractions, 1, 'the helper deleting the conversation is treated as scam');
        assert.match(t.seen.records[0].reason, /dm-helper deleted/);
        assert.match(t.seen.records[0].content, /check inbox/, 'the deleted text is kept as evidence');
        assert.strictEqual(t.seen.forwarded.length, 0, 'not posted to #ai (that channel is only for Discord invites)');
        await t.deleted({ id: 'offer1' });
        assert.strictEqual(t.seen.infractions, 1, 'flagged once, not per deletion');
    } finally { t.done(); }
});

test('DM watch: only an offer to another member is watched, and one conversation is flagged once', async () => {
    const t = setup({ intent: 'help-seeking' });
    try {
        // A help-seeker asking staff for a DM, then deleting their own question, is not a scammer.
        const ask = msg(ANSWER_CH, 'can a mod dm me please', { id: 'ask2', replyTo: { id: 's1', authorId: 'staff1' } });
        ask.guild.members.fetch = async (id) => (id === 'staff1' ? { roles: { cache: new Map([[STAFF_ROLE, {}]]) } } : ask.member);
        await t.handler(ask);
        await t.deleted({ id: 'ask2' });
        assert.strictEqual(t.seen.infractions, 0, 'asking staff for a DM is not watched');

        const noTarget = msg(ANSWER_CH, 'someone dm me', { id: 'ask3' });
        await t.handler(noTarget);
        await t.deleted({ id: 'ask3' });
        assert.strictEqual(t.seen.infractions, 0, 'a DM request addressed to nobody is not watched');

        // Ticket channels are private conversations with staff.
        const tk = setup({ intent: 'community-help' });
        try {
            const inTicket = msg('ticket-7', 'check inbox', { id: 'tk1', replyTo: { id: 'x1', authorId: 'seeker' } });
            inTicket.channel.parentId = 'ticketCat';
            inTicket.guild.members.fetch = async () => inTicket.member;
            await tk.handler(inTicket);
            await tk.deleted({ id: 'tk1' });
            assert.strictEqual(tk.seen.infractions, 0, 'ticket channels are never watched');
        } finally { tk.done(); }
    } finally { t.done(); }

    const t2 = setup({ intent: 'community-help' });
    try {
        for (const id of ['o1', 'o2']) {
            const m = msg(ANSWER_CH, 'check inbox', { id, replyTo: { id: 'q1', authorId: 'seeker' } });
            m.guild.members.fetch = async () => m.member;
            await t2.handler(m);
        }
        await t2.deleted({ id: 'o1' });
        await t2.deleted({ id: 'o2' });
        assert.strictEqual(t2.seen.infractions, 1, 'two DM requests in one conversation: one offence, not two');
    } finally { t2.done(); }
});

test('DM watch: a moderator deleting the message is not counted against the helper', async () => {
    const t = setup({ intent: 'community-help' });
    try {
        // Audit log: one entry for a moderator deleting user1's messages in this channel; `count` rises per delete.
        const entry = { id: 'a1', targetId: 'user1', executorId: 'mod1', executor: { id: 'mod1', tag: 'mod#1' }, createdTimestamp: Date.now() - 60 * 60 * 1000, extra: { channel: { id: ANSWER_CH }, count: 3 } };
        const guildAudit = async () => ({ entries: new Map([['a1', entry]]) });
        const offer = (id) => {
            const m = msg(ANSWER_CH, 'check inbox', { id, replyTo: { id: 'q1', authorId: 'seeker' } });
            m.guild.members.fetch = async () => m.member;
            m.guild.fetchAuditLogs = guildAudit;
            return m;
        };
        await t.handler(offer('w1'));
        await t.handler(offer('w2'));
        entry.extra.count = 4;   // the moderator deletes w1
        await t.deleted({ id: 'w1' });
        assert.strictEqual(t.seen.infractions, 0, 'a moderator deleted it: no offence');
        await t.deleted({ id: 'w2' });   // audit log unchanged: the helper deleted w2 themselves
        assert.strictEqual(t.seen.infractions, 1, 'the helper deleting their own message is still flagged');
    } finally { t.done(); }
});

test('scam blocker OFF: nothing is deleted', async () => {
    const t = setup({ intent: 'scam-content', scamBlocker: false });
    try {
        const userMsg = msg(OTHER_CH, 'dm me for help', { mentionBot: true });
        await t.handler(userMsg);
        assert.strictEqual(userMsg.deleted, undefined);
        assert.strictEqual(t.seen.infractions, 0);
    } finally { t.done(); }
});

// ─── Q&A learning ─────────────────────────────────────────────────────────────

test('Q&A learning: staff replies are learned only for real questions', async () => {
    const chat = setup({ intent: 'general-greeting' });
    try {
        await chat.handler(msg(ANSWER_CH, 'good morning everyone', { id: 'q1' }));
        await chat.handler(msg(ANSWER_CH, 'morning!', { staff: true, replyTo: { id: 'q1', authorId: 'user1' } }));
        assert.strictEqual(chat.seen.learned.length, 0, 'reply to a greeting is not learned');
    } finally { chat.done(); }

    const question = setup({ intent: 'help-seeking' });
    try {
        await question.handler(msg(ANSWER_CH, 'how do I claim my S6 airdrop?', { id: 'q2' }));
        await question.handler(msg(ANSWER_CH, 'connect your wallet on the airdrop page', { staff: true, replyTo: { id: 'q2', authorId: 'user1' } }));
        assert.strictEqual(question.seen.learned.length, 1, 'reply to a question is learned');
        assert.match(question.seen.learned[0].q, /claim my S6 airdrop/);
    } finally { question.done(); }
});
